mapper.select:
select BOOKSET_ID, BOOKSET_NAME, BOOKSET_TYPE, ACCT_MODE, ACCT_SUBJECT_ID, ACCT_SUBJECT_TYPE, STANDARD_CCY, BOOKSET_ID_TMPL, ACCT_STANDARD, START_DATE, END_DATE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME from BOK_BOOKSET WHERE 1 = 1
AND END_DATE >= #{start}
AND START_DATE <= #{end}
AND BOOKSET_ID IN
#{item}

select BOOKSET_ID prodId, BOOKSET_NAME prodName from BOK_BOOKSET where 1=1 and bookset_type!='01'
and (BOOKSET_NAME like concat(concat('%', #{groupName}),'%') or BOOKSET_ID like concat(concat('%', #{groupName}),'%') )
and ACCT_SUBJECT_TYPE != #{acctSubjectTypeNo}

select PRODUCT_ID prodId from SYS_BATCH_GRP_PRDLINK WHERE 1 = 1
AND GROUP_SEQ IN
#{item}

select TASK_ID from SYS_BATCH_JOB WHERE 1 = 1
AND BATCH_SEQ_NO IN
#{item}
